#include <stdio.h>

int max_toys(int price[], int n, int budget) {
    int count = 0;
    int spent = 0;
    for (int i = 0; i < n; i++) {
        if (spent + price[i] > budget) break;
        spent += price[i];
        count++;
    }
    return count;
}

