int content_children(int greed[], int cookie[], int n, int m) {
    int i = 0, j = 0;
    int count = 0;
    while (i < n && j < m) {
        if (cookie[j] >= greed[i]) {
            count++;
            i++;
        }
        j++;
    }
    return count;
}

