int can_serve(int bills[], int n) {
    int fives = 0, tens = 0;
    for (int i = 0; i < n; i++) {
        if (bills[i] == 5) {
            fives++;
        } else if (bills[i] == 10) {
            if (fives == 0) return 0;
            fives--;
            tens++;
        } else {
            if (tens > 0 && fives > 0) {
                tens--;
                fives--;
            } else if (fives >= 3) {
                fives -= 3;
            } else {
                return 0;
            }
        }
    }
    return 1;
}

