int min_join_cost(int n, int len[]) {
    int total = 0;
    int remaining = n;
    while (remaining > 1) {
        int i1 = -1, i2 = -1;
        for (int i = 0; i < n; i++) {
            if (len[i] == -1) continue;
            if (i1 == -1 || len[i] < len[i1]) {
                i2 = i1;
                i1 = i;
            } else if (i2 == -1 || len[i] < len[i2]) {
                i2 = i;
            }
        }
        int merged = len[i1] + len[i2];
        total += merged;
        len[i1] = merged;
        len[i2] = -1;
        remaining--;
    }
    return total;
}

