int min_candies(int n, int rating[]) {
    static int candy[10005];
    for (int i = 0; i < n; i++) candy[i] = 1;
    for (int i = 1; i < n; i++) {
        if (rating[i] > rating[i - 1] && candy[i] <= candy[i - 1]) {
            candy[i] = candy[i - 1] + 1;
        }
    }
    for (int i = n - 2; i >= 0; i--) {
        if (rating[i] > rating[i + 1] && candy[i] <= candy[i + 1]) {
            candy[i] = candy[i + 1] + 1;
        }
    }
    int total = 0;
    for (int i = 0; i < n; i++) total += candy[i];
    return total;
}

