void sort_weight(int weight[], int n) {
    for (int i = 1; i < n; i++) {
        int key = weight[i];
        int j = i - 1;
        while (j >= 0 && weight[j] > key) {
            weight[j + 1] = weight[j];
            j--;
        }
        weight[j + 1] = key;
    }
}

