int min_boats(int n, int weight[], int limit) {
    sort_weight(weight, n);
    int lo = 0, hi = n - 1;
    int boats = 0;
    while (lo <= hi) {
        if (weight[lo] + weight[hi] <= limit) lo++;
        hi--;
