void sort_jobs(int profit[], int deadline[], int n) {
    for (int i = 1; i < n; i++) {
        int p = profit[i];
        int d = deadline[i];
        int j = i - 1;
        while (j >= 0 && profit[j] < p) {
            profit[j + 1] = profit[j];
            deadline[j + 1] = deadline[j];
            j--;
        }
        profit[j + 1] = p;
        deadline[j + 1] = d;
    }
}

int max_deadline_profit(int n, int profit[], int deadline[]) {
    sort_jobs(profit, deadline, n);
    int used[101];
    for (int i = 0; i <= 100; i++) used[i] = 0;
    int total = 0;
    for (int i = 0; i < n; i++) {
        for (int s = deadline[i]; s >= 1; s--) {
            if (!used[s]) {
                used[s] = 1;
                total += profit[i];
                break;
            }
        }
    }
    return total;
}

