int min_removals(int n, int start[], int finish[]) {
    sort_by_finish(start, finish, n);
    int kept = 1;
    int last = finish[0];
    for (int i = 1; i < n; i++) {
        if (start[i] >= last) {
            kept++;
            last = finish[i];
        }
    }
    return n - kept;
}

