void sort_slots(int start[], int finish[], int n) {
    for (int i = 1; i < n; i++) {
        int s = start[i];
        int f = finish[i];
        int j = i - 1;
        while (j >= 0 && start[j] > s) {
            start[j + 1] = start[j];
            finish[j + 1] = finish[j];
            j--;
        }
        start[j + 1] = s;
        finish[j + 1] = f;
    }
}

int merge_slots(int n, int start[], int finish[], int outStart[], int outFinish[]) {
    sort_slots(start, finish, n);
    int m = 0;
    for (int i = 0; i < n; i++) {
        if (m > 0 && start[i] <= outFinish[m - 1]) {
            if (finish[i] > outFinish[m - 1]) outFinish[m - 1] = finish[i];
        } else {
            outStart[m] = start[i];
            outFinish[m] = finish[i];
            m++;
        }
    }
    return m;
}

