#include <stdio.h>

void sort_by_ratio(int weight[], int value[], int n) {
    for (int i = 1; i < n; i++) {
        int w = weight[i];
        int v = value[i];
        int j = i - 1;
        while (j >= 0 && (long long)value[j] * w < (long long)v * weight[j]) {
            weight[j + 1] = weight[j];
            value[j + 1] = value[j];
            j--;
        }
        weight[j + 1] = w;
        value[j + 1] = v;
    }
}

double fractional_knapsack(int n, int weight[], int value[], int W) {
    sort_by_ratio(weight, value, n);
    double total = 0.0;
    int cap = W;
    for (int i = 0; i < n; i++) {
        if (cap <= 0) break;
        if (weight[i] <= cap) {
            total += value[i];
            cap -= weight[i];
        } else {
            total += (double)value[i] * cap / weight[i];
            cap = 0;
        }
    }
    return total;
}

